import { GoogleGenAI, GenerateContentResponse, Type, Modality } from "@google/genai";
import { UploadedFile, StyleAnalysis, BackgroundMode, AspectRatio, FrameStyle, ImageResolution, ShapeType, TextPosition, FontCategory, RemixMode, TextSuggestionTone, FontModeOption } from "../types.ts";
import { STRICT_STYLE_RULES, ANALYSIS_PROMPT, IDENTITY_PARITY_PROTOCOL, STYLE_MASTER_PROTOCOL, SCENE_INTEGRITY_RULES, STRICT_STORY_COMPLIANCE_PROTOCOL, TYPOGRAPHIC_PARITY_PROTOCOL, ICON_REPLICATION_PROTOCOL } from "../constants.ts";

export const ensureApiKey = async (): Promise<boolean> => {
  if (window.aistudio && window.aistudio.hasSelectedApiKey) {
    const hasKey = await window.aistudio.hasSelectedApiKey();
    if (!hasKey) {
      if (window.aistudio.openSelectKey) {
        await window.aistudio.openSelectKey();
        return true;
      }
      return false;
    }
    return true;
  }
  return true;
};

const getClient = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
};

async function callWithRetry<T>(
  fn: () => Promise<T>,
  maxRetries: number = 4, 
  initialDelayMs: number = 1000 
): Promise<T> {
  let attempt = 0;
  while (attempt <= maxRetries) {
    try {
      return await fn();
    } catch (error: any) {
      const errorMsg = error?.message || '';
      if (errorMsg.includes('Requested entity was not found')) {
        if (window.aistudio?.openSelectKey) await window.aistudio.openSelectKey();
        throw error;
      }
      const isRetryable = errorMsg.includes('503') || errorMsg.includes('429') || errorMsg.includes('overloaded') || errorMsg.includes('UNAVAILABLE');
      if (isRetryable && attempt < maxRetries) {
        const delay = initialDelayMs * Math.pow(2, attempt);
        console.warn(`Model overloaded. Retrying in ${delay}ms... (Attempt ${attempt + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, delay));
        attempt++;
        continue;
      }
      throw error;
    }
  }
  throw new Error("Maximum retries exceeded. The model is currently under heavy load.");
}

export const analyzeStyle = async (files: UploadedFile[]): Promise<StyleAnalysis> => {
  return callWithRetry(async () => {
    const ai = getClient();
    const styleInfluencers = files.filter(f => f.isStyleInfluence);
    let prioritized: UploadedFile[] = [];
    if (styleInfluencers.length > 0) {
      prioritized = styleInfluencers.slice(0, 3);
    } else {
      prioritized = [
        ...files.filter(f => f.category === 'font'),
        ...files.filter(f => f.category === 'scene'),
        ...files.filter(f => f.category === 'icon'),
        ...files.filter(f => f.category === 'character').slice(0, 2)
      ].slice(0, 3);
    }

    const parts: any[] = prioritized.map(f => ({
      inlineData: { mimeType: f.mimeType, data: f.data }
    }));
    parts.push({ text: ANALYSIS_PROMPT });

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: parts },
      config: { responseMimeType: 'application/json' }
    });
    return JSON.parse(response.text || "{}");
  });
};

export const describeBaseImage = async (file: UploadedFile): Promise<string> => {
  return callWithRetry(async () => {
    const ai = getClient();
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: file.mimeType, data: file.data } },
          { text: "Describe the subjects, composition, and core visual elements of this image in a single paragraph." }
        ]
      }
    });
    return response.text || "";
  });
};

export const generateTextSuggestion = async (
  prompt: string, 
  tone: TextSuggestionTone, 
  fontMode: boolean, 
  references: UploadedFile[],
  keywords: string
): Promise<string> => {
  return callWithRetry(async () => {
    const ai = getClient();
    const parts: any[] = [];
    const fontRef = references.find(f => f.category === 'font');
    if (fontRef) {
      parts.push({ inlineData: { mimeType: fontRef.mimeType, data: fontRef.data } });
    }
    parts.push({ 
      text: `Generate a short caption (max 5 words) for: "${prompt}". Tone: ${tone}. Keywords: "${keywords}". Return ONLY text.` 
    });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: parts }
    });
    return response.text?.trim() || "";
  });
};

export const generateMagicRoll = async (
  keywords: string, 
  charRefs: UploadedFile[], 
  count: number = 10, 
  storyMode: boolean = false, 
  strictNoWords: boolean = false
): Promise<string[]> => {
  return callWithRetry(async () => {
    const ai = getClient();
    const parts: any[] = [];

    // Identify which character indices actually have uploaded files
    const availableCharIndices = Array.from(new Set(charRefs.map(f => f.charIndex ?? 0)));
    const tagRestriction = availableCharIndices.length > 0 
      ? `ONLY use character tags from this list: [${availableCharIndices.map(i => `@C${i+1}`).join(', ')}]. DO NOT mention other character tags.`
      : `DO NOT use any character tags (@C1, @C2, etc) as no characters are provided.`;

    const frontViews = charRefs.filter(f => f.category === 'character' && f.viewType === 'front').slice(0, 3);
    if (frontViews.length > 0) {
      frontViews.forEach((file, i) => {
        parts.push({ inlineData: { mimeType: file.mimeType, data: file.data } });
      });
    }

    let instruction = storyMode 
      ? `Generate exactly ${count} sequential art prompts as JSON array. 
         IMPORTANT: Every prompt MUST end with 'Text overlay: "[Dialogue or Narrative text]"' based on the scene's action.
         ${tagRestriction}`
      : `Generate exactly ${count} distinct art prompts as JSON array. ${tagRestriction}`;

    parts.push({ text: `${instruction} Context: ${keywords}` });
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: { parts: parts },
      config: {
        responseMimeType: 'application/json',
        responseSchema: { type: Type.ARRAY, items: { type: Type.STRING } }
      }
    });
    return JSON.parse(response.text || "[]");
  });
};

export const generateArt = async (
  prompt: string,
  influence: string,
  bgMode: BackgroundMode,
  customBgColor: string,
  aspectRatio: AspectRatio = '1:1', 
  resolution: ImageResolution,
  overlayText: string,
  textPosition: TextPosition,
  textColor: string,
  textStrokeColor: string,
  textStrokeSize: number,
  fontCategory: FontCategory,
  fontSize: number,
  fontEffects: string,
  frameStyle: FrameStyle,
  strictMode: boolean,
  strictNoWords: boolean,
  noFrames: boolean,
  baseImage: UploadedFile | null,
  analysis: StyleAnalysis,
  referenceFiles: UploadedFile[],
  shape: ShapeType,
  borderColor: string,
  borderThickness: number,
  autoTextColor: boolean,
  autoFontSize: boolean,
  autoStroke: boolean,
  remixMode: RemixMode,
  fontModeEnabled: boolean,
  fontModeOption: FontModeOption,
  bwOnly: boolean,
  coloringBook: boolean,
  useStagingCharacter: boolean,
  isSequential: boolean = false
): Promise<string> => {
  return callWithRetry(async () => {
    const ai = getClient();
    const parts: any[] = [];

    let apiAspectRatio: string = aspectRatio;
    if (aspectRatio === '8.5:11' || aspectRatio === 'A4') apiAspectRatio = '3:4'; 
    else if (aspectRatio === '2:1') apiAspectRatio = '16:9';

    const activeBgColor = bgMode === BackgroundMode.WHITE ? '#FFFFFF' : (bgMode === BackgroundMode.BLACK ? '#000000' : (bgMode === BackgroundMode.CUSTOM ? customBgColor : '#FFFFFF'));

    // Check if Icon Ref is present for default overrides
    const hasIconRef = referenceFiles.some(f => f.category === 'icon');

    // LAW 1: World Building vs Asset Mode
    let environmentalMandate = "";
    const forceEnvironment = bgMode === BackgroundMode.FULL_BACKGROUND && !hasIconRef;

    if (forceEnvironment && shape !== ShapeType.IMAGE_CUT) {
        environmentalMandate = `
        *** MODE: FULL CINEMATIC ENVIRONMENT ***
        1. RENDER FULL SCENERY: Scenery, architecture, and lighting must be fully rendered.
        `;
    } else {
        environmentalMandate = `
        *** MODE: TECHNICAL CANVAS ISOLATION (Solid ${activeBgColor}) ***
        1. ERASE ALL SCENERY: No rooms, no landscapes.
        2. SOLID BACKGROUND: Render the subject on a pure, flat, solid ${activeBgColor} background.
        `;
    }

    // SUPREME COLOR MANDATE
    const colorPalette = analysis.colors && analysis.colors.length > 0 
      ? analysis.colors.join(', ') 
      : "Detected from references";

    const colorMandate = `
    *** SUPREME CHROMATIC OVERRIDE (ABSOLUTE PRIORITY) ***
    1. THE USER HAS CHANGED THE COLOR PROFILE. THE NEW PALETTE IS: [${colorPalette}].
    2. DISCARD ALL COLORS from reference images (@C1, @icon, etc.) if they conflict with this palette.
    3. MANDATORY RECOLOR: If @icon is red and the palette is blue, RENDER IN BLUE.
    4. THE PALETTE [${colorPalette}] IS THE ONLY ALLOWED COLOR IDENTITY.
    `;

    // SPATIAL MANDATE FOR ICONS
    let spatialMandate = "";
    if (hasIconRef) {
        spatialMandate = `
        *** CANVAS SCALE & SPATIAL PARITY MANDATE ***
        1. CLONE MARGINS: Replicate the exact padding Surrounding the subject as seen in @icon.
        2. SUBJECT SCALE: Replicate the exact size of the subject relative to the frame. 
        3. NO ZOOM: Do not enlarge the subject. Keep it small/centered if @icon is small/centered.
        `;
    }

    let textCommand = (overlayText && overlayText.trim() && !strictNoWords) 
      ? `*** RENDER TEXT COMMAND: "${overlayText}" ***`
      : `*** STRICT NEGATIVE CONSTRAINT: ZERO TEXT HALLUCINATION. ***`;

    const hasFontRef = referenceFiles.some(f => f.category === 'font');
    const hasSceneRef = referenceFiles.some(f => f.category === 'scene');
    const styleMasters = referenceFiles.filter(f => f.isStyleInfluence);

    let systemInstructions = `
    *** ARTMIMIC V190: ICONIC MASTER & PIXEL-TRUTH ARCHITECTURE ***
    1. ${useStagingCharacter ? IDENTITY_PARITY_PROTOCOL : ""}
    2. ${styleMasters.length > 0 ? STYLE_MASTER_PROTOCOL : ""}
    3. ${hasFontRef ? TYPOGRAPHIC_PARITY_PROTOCOL : ""}
    4. ${hasIconRef ? ICON_REPLICATION_PROTOCOL : ""}
    5. GLOBAL RENDERING SPEC: ${analysis.technique}. 
    ${environmentalMandate}
    ${spatialMandate}
    ${textCommand}
    ${STRICT_STYLE_RULES}
    ${hasSceneRef && !hasIconRef ? SCENE_INTEGRITY_RULES : ""}
    `;

    // Start with global style references
    if (styleMasters.length > 0) {
      styleMasters.forEach((f) => parts.push({ inlineData: { mimeType: f.mimeType, data: f.data } }));
    }

    // Icon DNA
    if (hasIconRef) {
      const iconRef = referenceFiles.find(f => f.category === 'icon');
      if (iconRef) {
        parts.push({ text: `[ICONIC_MASTER_TEMPLATE] Anchor @icon (CLONE ART MEDIUM, TEXTURE, AND SCALE EXACTLY):` });
        parts.push({ inlineData: { mimeType: iconRef.mimeType, data: iconRef.data } });
      }
    }

    if (hasFontRef) {
      const fontRef = referenceFiles.find(f => f.category === 'font');
      if (fontRef) parts.push({ inlineData: { mimeType: fontRef.mimeType, data: fontRef.data } });
    }

    if (hasSceneRef && !hasIconRef) {
      const sceneRef = referenceFiles.find(f => f.category === 'scene');
      if (sceneRef) parts.push({ inlineData: { mimeType: sceneRef.mimeType, data: sceneRef.data } });
    }

    if (baseImage) {
        parts.push({ text: `[STRUCTURAL_BLUEPRINT] Remix Base:` });
        parts.push({ inlineData: { mimeType: baseImage.mimeType, data: baseImage.data } });
    }

    // IDENTITY DNA IS MOVED TO THE END OF THE CHAIN FOR MAXIMUM ATTENTION WEIGHT
    let scaleDirectives = "";
    if (useStagingCharacter) {
      const characters = referenceFiles.filter(f => f.category === 'character');
      const uniqueCharIndices = Array.from(new Set(characters.map(c => c.charIndex ?? 0))).sort((a, b) => a - b);

      uniqueCharIndices.forEach(idx => {
          const charViews = characters.filter(c => c.charIndex === idx);
          const ratio = charViews[0]?.heightRatio ?? 1.0;

          if (idx === 0) {
              scaleDirectives += `- @C1: ANCHOR IDENTITY (Height Reference 1.0x).\n`;
          } else {
              scaleDirectives += `- @C${idx + 1}: Render at exactly ${ratio}x the height of @C1.\n`;
          }

          parts.push({ text: `*** IDENTITY DNA MASTER BLUEPRINT @C${idx + 1}: CLONE THESE GEOMETRIC ANCHORS EXACTLY ***` });
          charViews.forEach((v) => {
              parts.push({ text: `Geometric Reference (View: ${v.viewType}):` });
              parts.push({ inlineData: { mimeType: v.mimeType, data: v.data } });
          });
      });
    }

    const finalPromptText = `
    *** VOID INTERNAL DEFAULTS: ANY GEOMETRIC DEVIATION FROM @C1 PIXELS IS A PRODUCTION FAILURE ***
    TASK: RENDER ONE (1) SINGLE UNIFIED IMAGE.
    SUBJECTS: "${prompt}"
    DIRECTIVES: "${influence}"

    *** SCALE PARITY MANDATE ***:
    ${scaleDirectives}

    *** ICON STYLE FIDELITY MANDATE ***:
    1. CLONE THE ART MEDIUM OF @icon: If @icon is a rough-edged woodblock print stencil, the output MUST be a rough-edged woodblock print stencil.
    2. CLONE THE FORMAT: If @icon is a white silhouette on a solid block, REPLICATE THAT EXACT FORMAT.
    3. CLONE THE SCALE: Replicate exact margins and subject-to-frame ratio.

    ${systemInstructions}

    ${colorMandate}
    *** FINAL CHROMATIC REMINDER: THE USER PALETTE [${colorPalette}] OVERRIDES ALL REFERENCE PIXELS. RENDER IN THESE COLORS OR THE OUTPUT IS A FAILURE. ***

    *** STICKER/UI NEGATIVE CONSTRAINT ***:
    ABSOLUTELY NO COLOR SWATCHES, HEX CODES, PANTONE BARS, OR @1/@2 LABELS. THESE ARE REFERENCE METADATA AND MUST NOT BE RENDERED.
    `;

    parts.push({ text: finalPromptText });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: parts },
      config: {
        imageConfig: {
          aspectRatio: apiAspectRatio as any,
          imageSize: resolution
        }
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data returned from production engine.");
  });
};

