  const [borderColor, setBorderColor] = useState('#ffffff');
  const [borderThickness, setBorderThickness] = useState(2);

  const [remixMode, setRemixMode] = useState<RemixMode>(RemixMode.REPAINT);

  const [fontModeEnabled, setFontModeEnabled] = useState(false);
  const [fontModeOption, setFontModeOption] = useState<FontModeOption>(FontModeOption.EXTRACT);

  const [autoTextColor, setAutoTextColor] = useState(true);
  const [autoFontSize, setAutoFontSize] = useState(true);
  const [autoStroke, setAutoStroke] = useState(true);

  const [isMagicRolling, setIsMagicRolling] = useState(false);
  const [magicRollOptions, setMagicRollOptions] = useState<string[]>([]);
  const [magicRollCount, setMagicRollCount] = useState(10);
  const [storyMode, setStoryMode] = useState(false);
  const [selectedIndices, setSelectedIndices] = useState<Set<number>>(new Set());
  const [isInfluenceOpen, setIsInfluenceOpen] = useState(false);
  const [lastFocusedField, setLastFocusedField] = useState<'prompt' | 'influence'>('prompt');

  const [isSuggestingText, setIsSuggestingText] = useState(false);
  const [suggestionTone, setSuggestionTone] = useState<TextSuggestionTone>(TextSuggestionTone.WITTY);
  const [textKeywords, setTextKeywords] = useState('');
  const [hasCopied, setHasCopied] = useState(false);
  const [isPasteStoryMode, setIsPasteStoryMode] = useState(false);

  const isLocked = appState !== AppState.ANALYZED && appState !== AppState.GENERATING && appState !== AppState.ERROR;
  const isGenerating = appState === AppState.GENERATING;

  // Ref for the dynamic textareas
  const textareaRefs = useRef<(HTMLTextAreaElement | null)[]>([]);

  // Filter character indices to ONLY those that have at least one uploaded image
  const activeCharIndices: number[] = Array.from(new Set<number>(
    stagingFiles
      .filter(f => f.category === 'character')
      .map(f => f.charIndex ?? 0)
  )).sort((a: number, b: number) => a - b);

  const hasIconRef = stagingFiles.some(f => f.category === 'icon');

  useEffect(() => {
    const hasFont = stagingFiles.some(f => f.category === 'font');
    if (hasFont) {
      if (!fontModeEnabled) {
        setFontModeEnabled(true);
        setFontModeOption(FontModeOption.EXTRACT);
        setTextPosition(TextPosition.BELOW);
        addLog('System: Font detected. Auto-enabling Extract Mode.', 'success');
      }
    }
  }, [stagingFiles]);

  useEffect(() => {
    const handlePaste = (e: ClipboardEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return;
      if (isLocked || isGenerating) return;

      const items = e.clipboardData?.items;
      if (!items) return;

      for (let i = 0; i < items.length; i++) {
        if (items[i].type.indexOf('image') !== -1) {
          const blob = items[i].getAsFile();
          if (blob) {
            const reader = new FileReader();
            reader.onloadend = () => {
              const base64 = reader.result as string;
              setBaseImage({
                id: Math.random().toString(36).substr(2, 9),
                data: base64.split(',')[1],
                mimeType: blob.type
              });
            };
            reader.readAsDataURL(blob);
            break; 
          }
        }
      }
    };

    window.addEventListener('paste', handlePaste);
    return () => window.removeEventListener('paste', handlePaste);
  }, [isLocked, isGenerating]);

  // Adjust heights of all textareas when magicRollOptions changes
  useEffect(() => {
    magicRollOptions.forEach((_, i) => {
      const el = textareaRefs.current[i];
      if (el) {
        el.style.height = 'auto';
        el.style.height = el.scrollHeight + 'px';
      }
    });
  }, [magicRollOptions]);

  const handleCreatePages = () => {
    const newPages = new Array(magicRollCount).fill('');
    setMagicRollOptions(newPages);
    setSelectedIndices(new Set(newPages.map((_, i) => i)));
    addLog(`System: Created ${magicRollCount} blank prompt pages.`, 'action');
  };

  const handleMagicRoll = async () => {
    setIsMagicRolling(true);
    setMagicRollOptions([]);
    setSelectedIndices(new Set());
    const charRefs = stagingFiles.filter(f => f.category === 'character');

    try {
      const options = await generateMagicRoll(
        magicKeywords, 
        charRefs, 
        magicRollCount, 
        storyMode, 
        strictNoWords,
        useStagingCharacter
      );
      setMagicRollOptions(options);
      setSelectedIndices(new Set(options.map((_, i) => i)));
    } catch (error) {
      console.error("Magic Roll failed:", error);
    } finally {
      setIsMagicRolling(false);
    }
  };

  const handleEditRoll = (idx: number, newVal: string) => {
    const next = [...magicRollOptions];
    next[idx] = newVal;
    setMagicRollOptions(next);

    // Auto-resize specifically for the one being edited
    const el = textareaRefs.current[idx];
    if (el) {
      el.style.height = 'auto';
      el.style.height = el.scrollHeight + 'px';
    }

    if (selectedIndices.size === 1 && selectedIndices.has(idx)) {
      setPrompt(newVal);
    }
  };

  const handleToggleRoll = (idx: number) => {
    const next = new Set(selectedIndices);
    if (next.has(idx)) {
      next.delete(idx);
    } else {
      next.add(idx);
    }
    setSelectedIndices(next);
    if (next.size === 1) {
      setPrompt(magicRollOptions[Array.from(next)[0]]);
    }
  };

  const handleSelectAll = () => {
    if (selectedIndices.size === magicRollOptions.length) {
      setSelectedIndices(new Set());
    } else {
      setSelectedIndices(new Set(magicRollOptions.map((_, i) => i)));
    }
  };

  const handleCopyAll = () => {
    if (magicRollOptions.length === 0) return;
    const textToCopy = magicRollOptions.map((opt, i) => `${storyMode ? `Scene ${i + 1}` : `Idea ${i + 1}`}:\n${opt}`).join('\n\n');
    navigator.clipboard.writeText(textToCopy).then(() => {
      setHasCopied(true);
      setTimeout(() => setHasCopied(false), 2000);
    });
  };

  const handleDeleteTextOverlays = () => {
    if (magicRollOptions.length === 0) return;

    // Catch variants like: Text Overlay: "Text", Text overlay: Text, OverlayText: "Text", etc.
    const textOverlayRegex = /\s*(?:Text\s+overlay|TextOverlay|OverlayText|Text\s+overlay\s+text):\s*(?:"[^"]*"|[^\n\r,]+)/gi;

    const next = magicRollOptions.map(opt => {
      return opt.replace(textOverlayRegex, '').trim();
    });

    setMagicRollOptions(next);
    if (selectedIndices.size === 1) {
        setPrompt(next[Array.from(selectedIndices)[0]]);
    }
    addLog('System: Stripped text overlays from all scenes.', 'action');
  };

  const handleScenePaste = (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    if (!isPasteStoryMode) return;
    const pastedText = e.clipboardData.getData('text');

    const sceneDelimiter = /(?=(?:SCENE|Scene|scene)\s+\d+)/gi;
    const sceneCheck = /(?:SCENE|Scene|scene)\s+\d+/i;

    // Split by scenes first
    const chunks = pastedText.split(sceneDelimiter);
    let finalPages: string[] = [];

    chunks.forEach(chunk => {
      const trimmedChunk = chunk.trim();
      if (!trimmedChunk) return;

      if (sceneCheck.test(trimmedChunk)) {
        // This is a "Scene #" block. It is ONE page.
        finalPages.push(trimmedChunk);
      } else {
        // This chunk does not start with a Scene marker.
        // Rule: Each line represents one page.
        const lines = trimmedChunk.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
        finalPages.push(...lines);
      }
    });

    if (finalPages.length > 0) {
      e.preventDefault();
      setMagicRollOptions(finalPages);
      setSelectedIndices(new Set(finalPages.map((_, i) => i)));
      addLog(`System: Content segmented into ${finalPages.length} prompt pages.`, 'success');
    }
  };

  const insertMention = (tag: string) => {
    const mention = `${tag} `;
    if (lastFocusedField === 'influence') setMagicKeywords(prev => prev + mention);
    else setPrompt(prev => prev + mention);
  };

  const handleTextSuggestion = async () => {
    setIsSuggestingText(true);
    try {
      const suggestion = await generateTextSuggestion(prompt, suggestionTone, fontModeEnabled, stagingFiles, textKeywords);
      if (suggestion) setOverlayText(suggestion);
    } catch (error) {
      console.error("AI Text suggestion failed:", error);
    } finally {
      setIsSuggestingText(false);
    }
  };

  const handleGenerateClick = () => {
    let promptsToRun: string[] = [];
    if (selectedIndices.size > 0) {
      promptsToRun = Array.from(selectedIndices).map(idx => magicRollOptions[idx]);
    } else if (prompt.trim()) {
      promptsToRun = [prompt];
    }

    if (promptsToRun.length > 0 || baseImage || overlayText.trim() || fontModeEnabled) {
      onGenerate(
        promptsToRun, magicKeywords, bgMode, customBgColor, aspectRatio, resolution, 
        overlayText, textPosition, textColor, textStrokeColor, textStrokeSize,
        fontCategory, fontSize, fontEffects, frameStyle, strictMode, strictNoWords, 
        noFrames, baseImage, shape, borderColor, borderThickness, autoTextColor, 
        autoFontSize, autoStroke, remixMode, fontModeEnabled, fontModeOption, 
        bwOnly, coloringBook, useStagingCharacter, storyMode
      );
    }
  };

  const handleBaseImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
        const file = e.target.files[0];
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64 = reader.result as string;
            setBaseImage({
                id: Math.random().toString(36).substr(2, 9),
                data: base64.split(',')[1],
                mimeType: file.type
            });
        };
        reader.readAsDataURL(file);
    }
  };

  const handleRemoveBaseImage = () => {
      setBaseImage(null);
      setIsEnlargingBase(false);
  };

  const addLog = (message: string, type: 'info' | 'system' | 'action' | 'success' | 'error' = 'info') => {
      console.log(`[ArtGenerator] ${type.toUpperCase()}: ${message}`);
  };

  const isButtonDisabled = isGenerating || (!baseImage && !prompt.trim() && selectedIndices.size === 0 && !overlayText.trim() && !fontModeEnabled);
  const currentBaseUrl = baseImage ? `data:${baseImage.mimeType};base64,${baseImage.data}` : null;
  const showComparison = isEnlargingBase && latestResult && currentBaseUrl && latestResult.baseImageUrl === currentBaseUrl;

  // Show single prompt override only if no pages exist or if exactly one page is being focused in sync
  const hideSingleOverride = magicRollOptions.length > 0;

  const MentionButtons = () => (
    <div className="flex items-center gap-2 bg-slate-900/50 p-1 px-2 rounded-lg border border-slate-800">
        <span className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter">Mentions:</span>
        <div className="flex gap-1 flex-wrap">
            {activeCharIndices.map(idx => (
                <button 
                    key={idx} 
                    onClick={() => insertMention(`@C${idx + 1}`)}
                    className="text-[9px] bg-indigo-600/20 hover:bg-indigo-600 text-indigo-300 px-1.5 rounded font-black border border-indigo-500/30 transition-all"
                >
                    @C{idx + 1}
                </button>
            ))}
            {hasIconRef && (
                <button 
                    onClick={() => insertMention('@icon')}
                    className="text-[9px] bg-amber-600/20 hover:bg-amber-600 text-amber-300 px-1.5 rounded font-black border border-amber-500/30 transition-all"
                >
                    @icon
                </button>
            )}
        </div>
    </div>
  );

  return (
    <div className={`relative transition-opacity duration-500 ${isLocked ? 'opacity-40 pointer-events-none grayscale' : 'opacity-100'}`}>
      <h2 className="text-xl font-bold text-slate-100 mb-4">3. Art Generator</h2>
      <div className="bg-slate-900 border border-slate-700 rounded-xl p-6 space-y-6 pb-24 relative overflow-visible shadow-2xl">

        {/* Environment & Background Section */}
        <div className="p-4 bg-slate-800/30 rounded-lg border border-slate-700 space-y-4 shadow-inner">
            <div className="flex justify-between items-center">
                <label className="block text-xs uppercase tracking-wider text-slate-400 font-bold">Background Environment</label>
                <div className="flex gap-2">
                    {[BackgroundMode.FULL_BACKGROUND, BackgroundMode.WHITE, BackgroundMode.BLACK, BackgroundMode.CUSTOM].map((mode) => (
                        <button 
                            key={mode} 
                            onClick={() => setBgMode(mode)}
                            className={`px-3 py-1 rounded text-[10px] font-black uppercase transition-all border ${bgMode === mode ? 'bg-blue-600 border-blue-400 text-white' : 'bg-slate-900 border-slate-700 text-slate-500'}`}
                        >
                            {mode === BackgroundMode.FULL_BACKGROUND ? 'Full Art' : mode === BackgroundMode.CUSTOM ? 'Picker' : mode}
                        </button>
                    ))}
                </div>
            </div>
            {bgMode === BackgroundMode.CUSTOM && (
                <div className="flex items-center gap-4 animate-fade-in bg-slate-900 p-3 rounded-lg border border-slate-700">
                    <input 
                        type="color" 
                        value={customBgColor} 
                        onChange={(e) => setCustomBgColor(e.target.value)}
                        className="w-10 h-10 rounded cursor-pointer bg-transparent border-none"
                    />
                    <div className="flex flex-col">
                        <span className="text-[10px] text-slate-500 font-bold uppercase">Custom Backdrop Hex</span>
                        <input 
                            type="text" 
                            value={customBgColor} 
                            onChange={(e) => setCustomBgColor(e.target.value)}
                            className="bg-transparent text-sm font-mono text-blue-400 focus:outline-none"
                        />
                    </div>
                </div>
            )}
            {(bgMode === BackgroundMode.WHITE || bgMode === BackgroundMode.BLACK || bgMode === BackgroundMode.CUSTOM) && (
              <p className="text-[10px] text-amber-500 font-bold uppercase tracking-widest animate-pulse">
                *** Strict Background Protocol Enabled: Zero Scenery Mode ***
              </p>
            )}
        </div>

        {/* Base Image Section */}
        <div>
            <div className="flex items-center justify-between mb-2">
              <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold">Base Image (Remix Mode)</label>
              {!baseImage && <span className="text-[10px] text-slate-600 font-mono">Supports Ctrl+V</span>}
            </div>
            {!baseImage ? (
                <div className="border border-dashed border-slate-700 rounded-lg p-4 bg-slate-800/50 hover:bg-slate-800 transition-all group">
                    <label className="cursor-pointer flex flex-col items-center justify-center gap-2 text-slate-400 group-hover:text-blue-400">
                        <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2-2v12a2 2 0 002 2z"></path></svg>
                        <span className="text-sm font-medium">Upload or <span className="text-blue-500 font-bold">Paste (Ctrl+V)</span> to Remix</span>
                        <input type="file" accept="image/*" onChange={handleBaseImageSelect} className="hidden" disabled={isLocked || isGenerating} />
                    </label>
                </div>
            ) : (
                <div className="space-y-4">
                  <div className="relative w-full h-40 bg-slate-800 rounded-lg overflow-hidden border border-slate-600 group shadow-inner">
                      <img src={`data:${baseImage.mimeType};base64,${baseImage.data}`} alt="Base" className="w-full h-full object-cover opacity-90 cursor-zoom-in" onClick={() => setIsEnlargingBase(true)} />
                      <div className="absolute top-2 left-2 pointer-events-none">
                           <span className="text-[10px] font-bold text-white bg-blue-600/80 backdrop-blur-sm px-2 py-0.5 rounded uppercase shadow-md">REMIX SOURCE</span>
                      </div>
                      <div className="absolute inset-0 bg-black/20 flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                           <button onClick={() => setIsEnlargingBase(true)} className="text-xs bg-slate-100 text-slate-900 font-bold px-3 py-1.5 rounded-lg hover:bg-white shadow-xl transition-all">
                              {showComparison ? 'Compare Before/After' : 'Enlarge'}
                           </button>
                           <button onClick={handleRemoveBaseImage} className="text-xs bg-red-600 text-white font-bold px-3 py-1.5 rounded-lg hover:bg-red-500 shadow-xl transition-all">Remove</button>
                      </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3 animate-fade-in">
                      <div onClick={() => setRemixMode(RemixMode.REPAINT)} className={`flex items-center gap-2 p-3 rounded-lg border cursor-pointer transition-all ${remixMode === RemixMode.REPAINT ? 'bg-blue-600/20 border-blue-500 text-blue-200 shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700'}`}>
                        <input type="checkbox" checked={remixMode === RemixMode.REPAINT} readOnly className="w-4 h-4 rounded-full border-slate-600 text-blue-500" />
                        <div className="flex flex-col">
                          <span className="text-xs font-bold uppercase">Repaint (Trace)</span>
                          <span className="text-[9px] opacity-70 leading-tight">Literal structure lock.</span>
                        </div>
                      </div>
                      <div onClick={() => setRemixMode(RemixMode.RERENDER)} className={`flex items-center gap-2 p-3 rounded-lg border cursor-pointer transition-all ${remixMode === RemixMode.RERENDER ? 'bg-purple-600/20 border-purple-500 text-purple-200 shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700'}`}>
                        <input type="checkbox" checked={remixMode === RemixMode.RERENDER} readOnly className="w-4 h-4 rounded-full border-slate-600 text-purple-500" />
                        <div className="flex flex-col">
                          <span className="text-xs font-bold uppercase">Rerender (Re-imagine)</span>
                          <span className="text-[9px] opacity-70 leading-tight">Prompt-based reimagining.</span>
                        </div>
                      </div>
                  </div>
                </div>
            )}
        </div>

        {/* Prompt Section */}
        <div className="space-y-3">
            <div className="flex justify-between items-center">
                <div className="flex items-center gap-3">
                    <label className="block text-xs uppercase tracking-wider text-slate-500 font-bold">Subject Prompt</label>
                    <div className="flex items-center gap-1.5 bg-slate-800/80 px-2 py-0.5 rounded border border-slate-700">
                        <input type="checkbox" id="useStagingCharacter" checked={useStagingCharacter} onChange={(e) => setUseStagingCharacter(e.target.checked)} className="w-3 h-3 text-indigo-500 rounded border-slate-600 focus:ring-indigo-500" />
                        <label htmlFor="useStagingCharacter" className="text-[9px] font-black text-slate-400 uppercase cursor-pointer hover:text-indigo-400">Use Main Ref</label>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                   <button onClick={() => setIsInfluenceOpen(!isInfluenceOpen)} className={`px-3 py-1 rounded-full border text-[10px] font-black uppercase tracking-widest transition-all ${isInfluenceOpen ? 'bg-indigo-600 text-white border-white shadow-indigo-500/20' : 'bg-slate-800 border-slate-700 text-indigo-400 hover:text-indigo-300 shadow-lg'}`}>
                     {isInfluenceOpen ? 'Close Influence' : (magicKeywords.trim() ? '✨ Influence Set' : 'Set Influence')}
                   </button>
                   <div className="flex flex-col items-center gap-1">
                      <div className="flex items-center gap-1 bg-indigo-950/50 border border-indigo-900/50 rounded-full px-2 py-0.5">
                           <span className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter">Cnt:</span>
                           <input 
                               type="number" 
                               min="1" 
                               max="30" 
                               value={magicRollCount} 
                               onChange={(e) => setMagicRollCount(parseInt(e.target.value) || 1)}
                               className="w-10 bg-transparent text-[10px] font-mono text-white focus:outline-none"
                           />
                      </div>
                      <button 
                          onClick={handleCreatePages}
                          className="w-full text-[7px] bg-slate-800 hover:bg-slate-700 text-slate-400 px-2 py-1 rounded border border-slate-700 font-black uppercase tracking-widest transition-all"
                      >
                          Create Pages
                      </button>
                   </div>
                    <button onClick={handleMagicRoll} disabled={isLocked || isGenerating || isMagicRolling} className={`flex items-center gap-1.5 px-3 py-1 rounded-full border text-[10px] font-black uppercase tracking-widest transition-all ${isMagicRolling ? 'bg-indigo-600/50 border-indigo-400 text-white animate-pulse' : 'bg-indigo-950 border-indigo-700 text-indigo-400 hover:bg-indigo-900 hover:text-indigo-200 shadow-lg active:scale-95'}`}>
                      {isMagicRolling ? 'Synthesizing...' : `🎲 Magic Roll`}
                    </button>
                </div>
            </div>
            {isInfluenceOpen && (
              <div className="animate-fade-in-down border-l-4 border-indigo-600 pl-4 bg-indigo-900/10 p-4 rounded-r-xl space-y-3">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <label className="block text-[10px] font-black text-indigo-400 uppercase tracking-widest">Custom Influence / Story</label>
                        <MentionButtons />
                    </div>
                    <div className="flex items-center gap-1.5 bg-indigo-950 px-3 py-1 rounded border border-indigo-800">
                        <input 
                            type="checkbox" 
                            id="storyMode" 
                            checked={storyMode} 
                            onChange={(e) => setStoryMode(e.target.checked)} 
                            className="w-3.5 h-3.5 rounded border-indigo-700 text-indigo-500" 
                        />
                        <label htmlFor="storyMode" className="text-[10px] font-black text-white uppercase tracking-tighter cursor-pointer">Story Mode</label>
                    </div>
                </div>
                <textarea 
                    value={magicKeywords} 
                    onChange={(e) => setMagicKeywords(e.target.value)} 
                    onFocus={() => setLastFocusedField('influence')}
                    placeholder={storyMode ? "INSERT YOUR FULL STORY HERE. ArtMimic will generate sequential scenes with narrative overlays." : "PRIMARY DIRECTIVE FOR THE AI ART DIRECTOR."} 
                    className="w-full bg-slate-950 border border-indigo-900/50 rounded-lg px-4 py-3 text-indigo-200 text-xs focus:outline-none focus:border-indigo-500 shadow-inner min-h-[160px] resize-y font-mono leading-relaxed" 
                    rows={8} 
                />
              </div>
            )}

            {!hideSingleOverride && (
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] text-slate-500 font-bold uppercase tracking-widest ml-1">Manual Prompt Override</label>
                    <MentionButtons />
                </div>
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onFocus={() => setLastFocusedField('prompt')}
                  placeholder={baseImage ? "Describe transformation..." : "Describe the subject scenario... Use @C1 to mention Character 1."} 
                  className="w-full bg-slate-800 border border-slate-600 rounded-lg px-4 py-3 text-slate-200 focus:outline-none focus:border-blue-500 shadow-inner resize-y font-mono text-sm leading-relaxed" 
                  rows={6}
                  disabled={isLocked || isGenerating} 
                />
              </div>
            )}

            {magicRollOptions.length > 0 && (
              <div className="bg-slate-950/80 border border-indigo-900/50 rounded-xl p-4 space-y-4 max-h-[600px] overflow-y-auto console-scroll animate-fade-in mb-4">
                <div className="flex justify-between items-center mb-2 pb-2 border-b border-indigo-900/30 sticky top-0 bg-slate-950 z-10">
                  <div className="flex items-center gap-4">
                    <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">{storyMode ? 'Storyboards' : 'Prompt Pages'}</span>
                    <div className="flex flex-wrap gap-2">
                        <button onClick={handleSelectAll} className="text-[10px] bg-indigo-900/50 border border-indigo-700 text-indigo-300 px-3 py-1 rounded hover:bg-indigo-800 transition-colors uppercase font-bold">
                        {selectedIndices.size === magicRollOptions.length ? 'Deselect All' : 'Select All'}
                        </button>
                        <button onClick={handleCopyAll} className={`text-[10px] ${hasCopied ? 'bg-emerald-600 border-emerald-400 text-white' : 'bg-slate-800 border-slate-700 text-slate-400'} px-3 py-1 rounded hover:opacity-80 transition-all uppercase font-bold flex items-center gap-1`}>
                        {hasCopied ? 'Copy All' : 'Copy All'}
                        </button>
                        <div className="flex items-center gap-1.5 bg-slate-800/80 px-2 py-1 rounded border border-slate-700 ml-1">
                            <input 
